-- Make the seeded placeholder bulk-upload template bank-neutral (no bank names).
-- Existing debit accounts keep pointing at the same row (same id).
update public.bank_templates
   set key = 'bulk_placeholder', name = 'Bank bulk upload (placeholder — verify against your bank''s latest template)', config = '{"key":"bulk_placeholder","name":"Bank bulk upload (placeholder — verify against your bank''s latest template)","isPlaceholder":true,"notes":"Placeholder layout modelled on a typical corporate net-banking bulk payment file. Verify column order, mode codes and limits against your bank''s own bulk-upload template before uploading.","version":1,"fileType":"csv","delimiter":",","includeHeader":true,"lineEnding":"CRLF","trailingNewline":true,"quote":"auto","bom":false,"sheetName":"Payments","columns":[{"header":"Payment Mode","field":"paymentMode"},{"header":"Beneficiary Name","field":"beneficiaryName"},{"header":"Beneficiary Account No","field":"accountNumber","maxLength":18},{"header":"IFSC","field":"ifsc","maxLength":11},{"header":"Amount","field":"amount"},{"header":"Debit Account No","field":"debitAccount","maxLength":18},{"header":"Value Date","field":"valueDate"},{"header":"Remarks/Narration","field":"remarks"},{"header":"Beneficiary Email","field":"email","maxLength":50},{"header":"Beneficiary Mobile","field":"phone","maxLength":10}],"formats":{"dateFormat":"DD/MM/YYYY","amountDecimals":2},"text":{"allowedChars":"A-Za-z0-9 .\\-/","maxNameLength":35,"maxRemarksLength":30,"uppercase":false},"paymentModeRule":{"rtgsMinPaise":20000000,"defaultMode":"NEFT","sameBankMode":"FT","allowRtgs":true,"allowImps":false,"impsMaxPaise":50000000,"modeCodes":{"NEFT":"N","RTGS":"R","IMPS":"M","FT":"I"}},"maxRowsPerFile":500,"newPayeesAllowed":"unknown"}'::jsonb, updated_at = now()
 where workspace_id is null and is_system and key <> 'generic_csv';
